state Pushed
{
  ignores Bump; //UTPT didn't add this for some reason -AdamJD

  function BeginState()
  {
    Super.BeginState();
    bCoopPushLandingPending = False;
  }

  function EndState()
  {
    bCoopPushLandingPending = False;
    Super.EndState();
  }

  event Tick(float DeltaTime)
  {
    // The normal global tick advances the original post-cut countdown.
    Global.Tick(DeltaTime);
    if (bCoopPushLandingPending && CoopCombatMayAct())
    {
      bCoopPushLandingPending = False;
      // Replay only this previously observed callback, never infer a landing
      // from Physics or force a state based on elapsed time.
      Landed(CoopPushLandingNormal);
    }
  }

  function Landed (Vector HitNormal)
  {
    if (!CoopCombatMayAct())
    {
      if (IsCh1CoopCombat() && !bCoopPushLandingPending)
      {
        bCoopPushLandingPending = True;
        CoopPushLandingNormal = HitNormal;
      }
      return;
    }
    bCoopPushLandingPending = False;
    Super.Landed(HitNormal);
    PlaySound(Sound'snail_land',SLOT_None);
    GotoState('RecoverFromPush');
  }

 begin:
  PlayAnim('Idle');
}

var bool StrafeLeft;
var bool bCoopCrabLandingPending;
var Vector CoopCrabLandingNormal;
var float CoopCrabLandingDistance;
var name CoopCrabLandingState;
var int CoopCrabStateEpoch, CoopCrabLandingEpoch;

// Only combat state generations participate in deferred AI recovery. A
// captured scripted state retains its own physical/state lifecycle.
function bool IsCoopCrabLandingState()
{
  return IsInState('patrol') || IsInState('stateIdle') || IsInState('AttackHarry')
    || IsInState('throwing') || IsInState('strafeAround')
    || IsInState('stateHitBySpell') || IsInState('DoFlip')
    || IsInState('FallOverLedge') || IsInState('stayFlipped');
}

function RetireCoopCrabLanding()
{
  CoopCrabStateEpoch++;
  bCoopCrabLandingPending = False;
}

function Landed(Vector HitNormal)
{
  if (IsCh1CoopCombat() && !CoopCombatMayAct())
  {
    if (IsCoopCrabLandingState() && !bCoopCrabLandingPending)
    {
      bCoopCrabLandingPending = True;
      CoopCrabLandingState = GetStateName();
      CoopCrabLandingEpoch = CoopCrabStateEpoch;
      CoopCrabLandingNormal = HitNormal;
      CoopCrabLandingDistance = fHighestZ - Location.Z;
    }
    return;
  }
  bCoopCrabLandingPending = False;
  Super.Landed(HitNormal);
}

function bool DrainCoopCrabLanding()
{
  if (!bCoopCrabLandingPending) return False;
  if (CoopCrabLandingEpoch != CoopCrabStateEpoch
      || CoopCrabLandingState != GetStateName())
  {
    bCoopCrabLandingPending = False;
    return False;
  }
  if (!CoopCombatMayAct()) return False;
  bCoopCrabLandingPending = False;
  // The real event supplied normal/height before capture could move the NPC.
  // This is the shared original callback body, not a synthetic Landed event.
  CompleteCrabLanding(CoopCrabLandingNormal, True, CoopCrabLandingDistance);
  // Stop the caller's old-state tick tail even if cleanup changed state.
  return True;
}

