// All source labels/BeginState behavior remain inherited.
state patrol
{
  function Tick(float DeltaTime)
  {
    if (IsCh1CoopCombat())
    {
      if (!CoopCombatMayAct() || DrainCoopCrabLanding()) return;
    }
    // HPawn.patrol.Tick has MoveSmooth after Global.Tick. Guard before it.
    Super.Tick(DeltaTime);
  }
  function EndState()
  {
    RetireCoopCrabLanding();
    Super.EndState();
  }
}

