  {
    if (IsCh1CoopCombat())
    {
      if (!CoopCombatMayAct() || DrainCoopCrabLanding()) return;
    }
    // Preserve original normal MoveSmooth exactly once, only when unowned.
    Super.Tick(DeltaTime);
  }
